function(container, apiUrl, tables) {
  let currentRecord = null;
  let workItems = [];
  let breakRecords = [];

  // 作業項目マスタを取得
  async function loadWorkItems() {
    const items = await window.aivicApi.list(3); // 作業項目マスタ
    if (items) {
      workItems = items.filter(item => item.有効フラグ);
      const select = container.querySelector("#select-work-item");
      select.innerHTML = '<option value="">選択してください</option>' +
        workItems.map(item => `<option value="${item.作業項目ID}">${item.作業項目名}</option>`).join("");
    }
  }

  // 作業記録一覧を取得してドロップダウンに設定
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録
    if (records) {
      const select = container.querySelector("#select-record");
      select.innerHTML = '<option value="">選択してください</option>' +
        records.map(record => {
          const date = new Date(record.作業日).toLocaleDateString();
          const project = record.プロジェクト名 || '';
          const content = record.作業内容 ? record.作業内容.substring(0, 20) + '...' : '';
          return `<option value="${record.作業記録ID}">${date} - ${project} - ${content}</option>`;
        }).join("");
    }
  }

  // 修正前データを表示
  function displayOriginalData(record) {
    const originalDataDiv = container.querySelector("#original-data");
    if (!record) {
      originalDataDiv.innerHTML = '<div style="color: var(--text-muted);">記録を選択してください</div>';
      return;
    }

    const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
    const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
    const workDate = new Date(record.作業日).toLocaleDateString();

    originalDataDiv.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>作業日:</strong> ${workDate}</div>
      <div style="margin-bottom: 8px;"><strong>開始時刻:</strong> ${startTime}</div>
      <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${endTime}</div>
      <div style="margin-bottom: 8px;"><strong>作業時間:</strong> ${record.作業時間 || 0}分</div>
      <div style="margin-bottom: 8px;"><strong>プロジェクト:</strong> ${record.プロジェクト名 || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>作業場所:</strong> ${record.作業場所 || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${record.作業種別 || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>進捗状況:</strong> ${record.進捗状況 || '-'}</div>
      <div><strong>作業内容:</strong> ${record.作業内容 || '-'}</div>
    `;
  }

  // 中断記録を表示
  async function displayBreakRecords(workRecordId) {
    const breaks = await window.aivicApi.list(2); // 中断記録
    const breakRecordsDiv = container.querySelector("#break-records");

    if (breaks) {
      const relatedBreaks = breaks.filter(b => b.作業記録ID === workRecordId);
      if (relatedBreaks.length === 0) {
        breakRecordsDiv.innerHTML = 'なし';
      } else {
        breakRecordsDiv.innerHTML = relatedBreaks.map(b => {
          const startTime = new Date(b.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
          const endTime = b.中断終了日時 ? new Date(b.中断終了日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '継続中';
          return `<div style="margin-bottom: 4px;">${startTime} - ${endTime} (${b.中断理由区分})</div>`;
        }).join("");
      }
      breakRecords = relatedBreaks;
    }
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = container.querySelector("#input-break-time").value;

    let actualWorkTime = 0;
    let breakDuration = 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      const totalMinutes = (end - start) / (1000 * 60);

      if (breakTime) {
        const breakStart = new Date(`2000-01-01T${breakTime}`);
        breakDuration = Math.max(0, (end - breakStart) / (1000 * 60));
      }

      actualWorkTime = Math.max(0, totalMinutes - breakDuration);
    }

    container.querySelector("#break-duration").textContent = `${breakDuration}分`;
    container.querySelector("#actual-work-time").textContent = `${actualWorkTime}分`;

    // 異常値チェック
    checkAnomalies(actualWorkTime, breakDuration);
  }

  // 異常値チェック
  function checkAnomalies(workTime, breakTime) {
    const warningArea = container.querySelector("#warning-area");
    const warningMessage = container.querySelector("#warning-message");
    let warnings = [];

    if (workTime > 480) { // 8時間超過
      warnings.push("作業時間が8時間を超えています");
    }
    if (workTime < 30 && workTime > 0) { // 30分未満
      warnings.push("作業時間が30分未満です");
    }
    if (breakTime > 120) { // 2時間超過
      warnings.push("中断時間が2時間を超えています");
    }

    if (warnings.length > 0) {
      warningMessage.textContent = warnings.join(", ");
      warningArea.classList.remove("hidden");
    } else {
      warningArea.classList.add("hidden");
    }
  }

  // 記録選択時の処理
  container.querySelector("#select-record").addEventListener("change", async function() {
    const recordId = this.value;
    if (!recordId) {
      currentRecord = null;
      displayOriginalData(null);
      container.querySelector("#break-records").innerHTML = 'なし';
      return;
    }

    const records = await window.aivicApi.list(1);
    if (records) {
      currentRecord = records.find(r => r.作業記録ID === recordId);
      if (currentRecord) {
        displayOriginalData(currentRecord);
        displayBreakRecords(recordId);

        // フォームに現在の値を設定
        const workDate = new Date(currentRecord.作業日);
        container.querySelector("#input-work-date").value = workDate.toISOString().split('T')[0];

        if (currentRecord.作業開始時刻) {
          const startTime = new Date(currentRecord.作業開始時刻);
          container.querySelector("#input-start-time").value = startTime.toTimeString().substring(0, 5);
        }

        if (currentRecord.作業終了時刻) {
          const endTime = new Date(currentRecord.作業終了時刻);
          container.querySelector("#input-end-time").value = endTime.toTimeString().substring(0, 5);
        }

        calculateTimes();
      }
    }
  });

  // 時間入力時の計算
  container.querySelector("#input-start-time").addEventListener("change", calculateTimes);
  container.querySelector("#input-end-time").addEventListener("change", calculateTimes);
  container.querySelector("#input-break-time").addEventListener("change", calculateTimes);

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", function() {
    container.querySelector("#select-record").value = "";
    container.querySelector("#input-work-date").value = "";
    container.querySelector("#input-start-time").value = "";
    container.querySelector("#input-end-time").value = "";
    container.querySelector("#select-work-item").value = "";
    container.querySelector("#input-break-time").value = "";
    container.querySelector("#select-break-reason").value = "";
    container.querySelector("#input-correction-reason").value = "";
    container.querySelector("#warning-area").classList.add("hidden");
    currentRecord = null;
    displayOriginalData(null);
    container.querySelector("#break-records").innerHTML = 'なし';
    calculateTimes();
  });

  // 修正保存ボタン
  container.querySelector("#btn-save").addEventListener("click", async function() {
    if (!currentRecord) {
      alert("修正対象の記録を選択してください");
      return;
    }

    const correctionReason = container.querySelector("#input-correction-reason").value.trim();
    if (!correctionReason) {
      alert("修正理由を入力してください");
      return;
    }

    const workDate = container.querySelector("#input-work-date").value;
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const workItemId = container.querySelector("#select-work-item").value;

    if (!workDate || !startTime) {
      alert("作業日付と開始時刻は必須です");
      return;
    }

    // 作業時間を計算
    let workTime = 0;
    if (startTime && endTime) {
      const start = new Date(`${workDate}T${startTime}`);
      const end = new Date(`${workDate}T${endTime}`);
      workTime = Math.max(0, (end - start) / (1000 * 60));
    }

    const updateData = {
      作業日: new Date(workDate).toISOString(),
      作業開始時刻: new Date(`${workDate}T${startTime}`).toISOString(),
      作業終了時刻: endTime ? new Date(`${workDate}T${endTime}`).toISOString() : null,
      作業時間: Math.round(workTime),
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(1, currentRecord.作業記録ID, updateData);
    if (updated) {
      // 中断記録の処理
      const breakTime = container.querySelector("#input-break-time").value;
      const breakReason = container.querySelector("#select-break-reason").value;

      if (breakTime && breakReason) {
        const breakData = {
          作業記録ID: currentRecord.作業記録ID,
          中断開始日時: new Date(`${workDate}T${breakTime}`).toISOString(),
          中断理由区分: breakReason,
          対応状況: "記録済み",
          記録者ID: currentRecord.作業員ID,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };
        await window.aivicApi.save(2, breakData);
      }

      alert("修正が完了しました");
      container.querySelector("#btn-reset").click();
    }
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", function() {
    window.showScreen("scr-1778907133295"); // 工数記録画面
  });

  // 履歴一覧ボタン
  container.querySelector("#btn-history").addEventListener("click", function() {
    window.showScreen("scr-1778907145716"); // 作業履歴一覧画面
  });

  // 初期化
  loadWorkItems();
  loadWorkRecords();
}
